comms.text:
@1 וִיהֵי אֲרֵי תֵעוּל לְאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא וְתֵירְתַהּ וְתֵיתֵב בַּהּ:
@2 וְתִסַב מֵרֵישׁ כָּל אִבָּא דְאַרְעָא דִי תָעֵל מֵאַרְעָךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ וּתְשַׁוֵי בְסַלָא וּתְהַךְ לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן:
@3 וְתֵיתֵי לְוָת כַּהֲנָא דִי יְהֵי בְּיוֹמַיָא הָאִנוּן וְתֵימַר לֵהּ חַוֵיתִי יוֹמָא דֵין קֳדָם יְיָ אֱלָהָךְ אֲרֵי עַלִית לְאַרְעָא דִי קַיִים יְיָ לַאֲבָהָתָנָא לְמִתַּן לָנָא:
@4 וְיִסַב כַּהֲנָא סַלָא מִידָךְ וְיַחְתִנֵהּ קֳדָם מַדְבְּחָא דַיְיָ אֱלָהָךְ:
@5 וְתָתֵיב וְתֵימַר קֳדָם יְיָ אֱלָהָךְ לָבָן אֲרָמָאָה בָּעָא לְאוֹבָדָא יָת אַבָּא וּנְחַת לְמִצְרַיִם וְדָר תַּמָן בְּעַם זְעֵר וַהֲוָה תַמָן לְעַם רַב תַּקִיף וְסַגִי:
@6 וְאַבְאִישׁוּ לָנָא מִצְרָאֵי וְעַנְיָנָא וִיהָבוּ עֲלָנָא פָּלְחָנָא קַשְׁיָא:
@7 וְצַלֵינָא קֳדָם יְיָ אֱלָהָא דַאֲבָהָתָנָא וְקַבִּיל יְיָ צְלוֹתָנָא וּגְלֵי קֳדָמוֹהִי עַמְלָנָא וְלֵאוּתָנָא וְדוּחֲקָנָא:
@8 וְאַפְּקָנָא יְיָ מִמִצְרַיִם בִּידָא תַקִיפָא וּבִדְרָעָא מְרַמְמָא וּבְחֶזְוָנָא רַבָּא וּבְאָתִין וּבְמוֹפְתִין:
@9 וְאַיְתָנָא לְאַתְרָא הָדֵין וִיהַב לָנָא יָת אַרְעָא הָדָא אַרְעָא עָבְדָא חֲלַב וּדְבָש:
@10 וּכְעַן הָא אַיְתֵתִי יָת רֵישׁ אִבָּא דְאַרְעָא דִיהַבְתְּ לִי יְיָ וְתַחְתִנֵהּ קֳדָם יְיָ אֱלָהָךְ וְתִסְגוּד קֳדָם יְיָ אֱלָהָךְ:
@11 וְתֶחֱדֵי בְכָל טַבְתָא דִי יְהַב לָךְ יְיָ אֱלָהָךְ וְלֶאֱנַשׁ בֵּיתָךְ אַתְּ וְלֵוָאֵי וְגִיוֹרָא דִי בֵינָךְ:
@12 אֲרֵי תְשֵׁצֵי לְעַשָׂרָא יָת כָּל מַעְשַׂר עֲלַלְתָּךְ בְּשַׁתָּא תְלִיתָאָה שְׁנַת מַעְשְׂרָא וְתִתֵּן לְלֵוָאֵי לְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא וְיֵכְלוּן בְּקִרְוָיךְ וְיִשְׂבְּעוּן:
@13 וְתֵימַר קֳדָם יְיָ אֱלָהָךְ פַּלֵתִי קֹדֶשׁ מַעְשְׂרָא מִן בֵּיתָא וְאַף יְהָבִתֵּהּ לְלֵוָאֵי וּלְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא כְּכָל פִּקוּדָךְ דִי פַקִדְתַּנִי לָא עֲבָרִית מִפִּקוּדָיךְ וְלָא אִתִּנְשֵׁיתִי:
@14 לָא אֲכָלִית בְּאֶבְלִי מִנֵהּ וְלָא פַלֵתִי מִנֵהּ בִּמְסָאָב וְלָא יְהָבִית מִנֵהּ לְמִית קַבֵּלִית לְמֵימְרָא דַיְיָ אֱלָהָי עֲבָדִית כְּכֹלּ דִי פַקִדְתַּנִי:
@15 אִסְתְּכִי מִמְדוֹר קוּדְשָׁךְ מִן שְׁמַיָא וּבָרֵךְ יָת עַמָךְ יָת יִשְׂרָאֵל וְיָת אַרְעָא דִי יְהַבְתְּ לָנָא כְּמָא דִי קַיֶמְתָּא לַאֲבָהָתָנָא אֲרַע עָבְדָא חֲלַב וּדְבָשׁ:
@16 יוֹמָא הָדֵין יְיָ אֱלָהָךְ מְפַקְדָךְ לְמֶעְבַּד יָת קְיָמַיָא הָאִלֵין וְיָת דִינַיָא וְתִטַר וְתַעְבֵּד יָתְהוֹן בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@17 יָת יְיָ חֲטַּבְתָּ יוֹמָא דֵין לְמֶהֱוֵי לָךְ לֶאֱלָהּ וְלִמְהַךְ בְּאָרְחָן דְתָקְנָן קֳדָמוֹהִי וּלְמִטַר קְיָמוֹהִי וּפִקוּדוֹהִי וְדִינוֹהִי וּלְקַבָּלָא לְמֵימְרֵהּ:
@18 וַיְיָ חָטְבָךְ יוֹמָא דֵין לְמֶהֱוֵי לֵהּ לְעַם חַבִּיב כְּמָא דִי מַלִיל לָךְ וּלְמִטַר כָּל פִּקוּדוֹהִי:
@19 וּלְמִתְּנָךְ עִלָאָה עַל כָּל עַמְמַיָא דִי עֲבַד לְתֻשְׁבָּחָא וּלְשׁוּם וְלִרְבוּ וּלְמֶהֱוָךְ עַם קַדִישׁ קֳדָם יְיָ אֱלָהָךְ כְּמָא דִי מַלִיל:
@20 וּפַקִיד מֹשֶׁה וְסָבֵי יִשְׂרָאֵל יָת עַמָא לְמֵימָר טַר יָת כָּל תַּפְקֶדְתָּא דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין:
@21 וִיהֵי בְּיוֹמָא דִי תַעְבְּרוּן יָת יַרְדְנָא לְאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ וּתְקִים לָךְ אַבְנִין רַבְרְבִין וּתְסוּד יָתְהוֹן בְּסִידָא:
@22 וְתִכְתּוֹב עֲלֵיהוֹן יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא בְּמֶעְבְּרָךְ בְּדִיל דִי תֵעוּל לְאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ אַרְעָא עָבְדָא חֲלַב וּדְבַשׁ כְּמָא דִי מַלִיל יְיָ אֱלָהָא דַאֲבָהָתָךְ לָךְ:
@23 וִיהֵי בְּמֵעֲבָרְכוֹן יָת יַרְדְנָא תְּקִימוּן יָת אַבְנַיָא הָאִלֵין דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין בְּטּוּרָא דְעֵיבָל וּתְסוּד יָתְהוֹן בְּסִידָא:
@24 וְתִבְנֵי תַמָן מַדְבְּחָא קֳדָם יְיָ אֱלָהָךְ מַדְבַּח אַבְנִין לָא תְרִים עֲלֵיהוֹן פַּרְזְלָא:
@25 אַבְנִין שָׁלְמִין תִּבְנֵי יָת מַדְבְּחָא דַיְיָ אֱלָהָךְ וְתַסֵק עֲלוֹהִי עֲלָוָן קֳדָם יְיָ אֱלָהָךְ:
@26 וְתִכּוֹס נִכְסַת קוּדְשִׁין וְתֵיכוּל תַּמָן וְתֶחֱדֵי קֳדָם יְיָ אֱלָהָךְ:
@27 וְתִכְתּוֹב עַל אַבְנַיָא יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא פָּרַשׁ יָאוּת:
@28 וּמַלִיל מֹשֶׁה וְכָהֲנַיָא לֵוָאֵי לְכָל יִשְׂרָאֵל לְמֵימָר אֲצֵית וּשְׁמַע יִשְׂרָאֵל יוֹמָא הָדֵין הֲוֵיתָא לְעַמָא קֳדָם יְיָ אֱלָהָךְ:
@29 וּתְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ וְתַעְבֵּד יָת פִּקוּדוֹהִי וְיָת קְיָמוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין:
@30 וּפַקִיד מֹשֶׁה יָת עַמָא בְּיוֹמָא הַהוּא לְמֵימָר:
@31 אִלֵין יְקוּמוּן לְבָרָכָא יָת עַמָא עַל טוּרָא דִגְרִזִים בְּמֵעֲבָרְכוֹן יָת יַרְדְנָא שִׁמְעוֹן וְלֵוִי וִיהוּדָה וְיִשָׂשכָר וְיוֹסֵף וּבִנְיָמִין:
@32 וְאִלֵין יְקוּמוּן עַל לְוָטַיָא בְּטוּרָא דְעֵיבָל רְאוּבֵן גָד וְאָשֵׁר וּזְבוּלֻן דָן וְנַפְתָּלִי:
@33 וִיתִיבוּן לֵוָאֵי וְיֵימְרוּן לְכָל אֱנַשׁ יִשְׂרָאֵל קָלָא רָמָא:
@34 לִיט גַבְרָא דִי יַעְבֵּד צֶלֶם וּמַתְּכָא מְרָחָקָא קֳדָם יְיָ עֹבַד יְדֵי אֳמָן וְשַׁוִי בְסִתְרָא וִיתִיבוּן כָּל עַמָא וְיֵימְרוּן אָמֵן:
@35 לִיטּ דְיִקְלֵי אֲבוּהִי וְאִמֵהּ וְיֵימַר כָּל עַמָא אָמֵן:
@36 לִיטּ דְיַשְׁנֵי תְּחוּמָא דְחַבְרֵהּ וְיֵימַר כָּל עַמָא אָמֵן:
@37 לִיט דְיַטְעֵי עַוִירָא בְּאָרְחָא וְיֵימַר כָּל עַמָא אָמֵן:
@38 לִיטּ דְיַצְלֵי דִין דַיַר יִתַּמָא וְאַרְמְלָא וְיֵימַר כָּל עַמָא אָמֵן:
@39 לִיט דְיִשְׁכּוּב עִם אִתַּת אֲבוּהִי אֲרֵי גַלִי כַּנְפָא דַאֲבוּהִי וְיֵימַר כָּל עַמָא אָמֵן:
@40 לִיט דְיִשְׁכּוּב עִם כָּל בְּעִירָא וְיֵימַר כָּל עַמָא אָמֵן:
@41 לִיט דְיִשְׁכּוּב עִם אֲחָתֵהּ בַּת אֲבוּהִי אוֹ בַת אִמֵהּ וְיֵימַר כָּל עַמָא אָמֵן:
@42 לִיט דְיִשְׁכּוּב עִם חֲמוֹתֵהּ וְיֵימַר כָּל עַמָא אָמֵן:
@43 לִיט דְיִמְחֵי לְחַבְרֵהּ בְּסִתְרָא וְיֵימַר כָּל עַמָא אָמֵן:
@44 לִיטּ דִי מְקַבֵּל שׂחֲדָא לְמִקְטַל נְפַשׁ דַם זַכַּי וְיֵימַר כָּל עַמָא אָמֵן:
@45 לִיט דִי לָא יְקַיַם יָת פִּתְגָמֵי אוֹרַיְתָא הָדָא לְמֶעְבַּד יָתְהוֹן וְיֵימַר כָּל עַמָא אָמֵן:
@46 וִיהֵי אִם קַבָּלָא תְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר לְמֶעְבַּד יָת כָּל פִּקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין וְיִתְּנִנָךְ יְיָ אֱלָהָךְ עִלָאָה עַל כָּל עַמְמֵי אַרְעָא:
@47 וְיֵיתוּן עֲלָךְ כָּל בִּרְכְּתָא הָאִלֵין וְיִדְבְּקֻנָךְ אֲרֵי תְקַבַּל לְמֵימְרָא דַיְיָ אֱלָהָךְ:
@48 בְּרִיךְ אַתְּ בְּקַרְתָּא וּבְרִיךְ אַתְּ בְּחַקְלָא:
@49 בְּרִיךְ וַלְדָא דִמְעָךְ וְאִבָּא דְאַרְעָךְ וּוַלְדָא דִבְעִירָךְ בַּקְרֵי תוֹרָיךְ וְעֶדְרֵי עָנָךְ:
@50 בְּרִיךְ סַלָךְ וְאַצְוָתָךְ:
@51 בְּרִיךְ אַתְּ בְּמֵעֲלָךְ וּבְרִיךְ אַתְּ בְּמִפְּקָךְ:
@52 יִתֵּן יְיָ יָת בַּעֲלֵי דְבָבָךְ דְקָיְמִין עֲלָךְ תְּבִירִין קֳדָמָךְ בְּאָרְחָא חַדָא יִפְּקוּן לְוָתָךְ וּבְשִׁבְעָא אָרְחָן יֵעִרְקוּן מִקֳדָמָךְ:
@53 יְפַקֵד יְיָ עִמָךְ יָת בִּרְכְּתָא בְּאוֹצָרָךְ וּבְכֹל אוֹשָׁטוּת יְדָךְ וִיבָרְכִנָךְ בְּאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@54 יְקִימִנָךְ יְיָ לֵהּ לְעַם קַדִישׁ כְּמָא דִי קַיִים לָךְ אֲרֵי תִטַר יָת פִּקוּדַיָא דַיְיָ אֱלָהָךְ וּתְהַךְ בְּאָרְחָן דְתָקְנָן קֳדָמוֹהִי:
@55 וְיֶחֱזוּן כָּל עַמְמֵי אַרְעָא אֲרֵי שְׁמָא דַיְיָ אִתְקְרֵי עֲלָךְ וְיִדְחֲלוּן מִנָךְ:
@56 וְיוֹתְרִנָךְ יְיָ לְטָבָא בְּוַלְדָא דִמְעָךְ וּבְוַלְדָא דִבְעִירָךְ וּבְאִבָּא דְאַרְעָךְ עַל אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתָךְ לְמִתַּן לָךְ:
@57 יִפְתַּח יְיָ לָךְ יָת אוֹצָרֵהּ טָבָא יָת שְׁמַיָא לְמִתַּן מְטַר אַרְעָךְ בְּעִדָנֵהּ וּלְבָרָכָא יָת כָּל עוֹבָדֵי יְדָךְ וְתוֹזֵף לְעַמְמִין סַגִיאִין וְאַתְּ לָא תְזוּף:
@58 וְיִתְּנִנָךְ יְיָ לְתַקִיף וְלָא לְחַלָשׁ וּתְהֵי בְּרַם לְעֵלָא וְלָא תְהֵי לְתַחְתָּא אֲרֵי תְקַבֵּל לְפִקוּדַיָא דַיְיָ אֱלָהָךְ דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמִטַר וּלְמֶעְבָּד:
@59 וְלָא תִסְטוּן מִכָּל פִּתְגָמַיָא דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין יַמִינָא וּשְׂמָאלָא לִמְהַךְ בָּתַר טַעֲוַת עַמְמַיָא לְמִפְלְחִנוּן:
@60 וִיהֵי אִם לָא תְקַבַּל בְּמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר לְמֶעְבַּד יָת כָּל פִּקוּדוֹהִי וּקְיָמוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין וְיֵיתוּן עֲלָךְ כָּל לְוָטַיָא הָאִלֵין וְיִדְבְּקֻנָךְ:
@61 לִיטּ אַתְּ בְּקַרְתָא וְלִיט אַתְּ בְּחַקְלָא:
@62 לִיט סַלָךְ וְאַצְוָתָךְ:
@63 לִיטּ וַלְדָא דִמְעָךְ וְאִבָּא דְאַרְעָךְ בַּקְרֵי תוֹרָיךְ וְעֶדְרֵי עָנָךְ:
@64 לִיט אַתְּ בְּמֵעֲלָךְ וְלִיט אַתְּ בְּמִפְּקָךְ:
@65 יְגָרֵי יְיָ בָּךְ יָת מֵאַרְתָּא וְיָת שִׁגוּשַׁיָא וְיָת מְזוֹפִיתָא בְּכָל אוֹשָׁטוּת יְדָךְ דִי תַעְבֵּד עַד דְתִשְׁתֵּצֵי וְעַד דְתֵיבַד בִּפְרִיעַ מִן קֳדָם בִּישׁוּת עוֹבָדָיךְ דִשְׁבַקְתָּא דַחַלְתִּי:
@66 יַדְבֵּק יְיָ בָּךְ יָת מוֹתָא עַד דִישֵׁיצֵי יָתָךְ מֵעַל אַרְעָא דִי אַתְּ עָלֵל לְתַמָן לְמִירְתַהּ:
@67 יִמְחִנָךְ יְיָ בְּשַׁחֶפְתָּא וּבְקַדַחְתָּא וּבִדְלֶקְתָּא וּבְחַרְחוּרָא וּבְחַרְבָּא וּבְשִׁדְפוֹנָא וּבְיַרְקוֹנָא וְיִרְדְפֻנָךְ עַד דְתֵיבָד:
@68 וִיהוֹן שְׁמַיָךְ דִי עִלָוֵי רֵישָׁךְ חֲסִינִין כִּנְחָשָׁא מִלְאֲחָתָא מִטְרָא וְאַרְעָא דִי תְחוֹתָךְ תַּקִיפָא כְפַרְזְלָא מִלְמֶעְבַּד פֵּרִין:
@69 יִתֵּן יְיָ יָת מְטַר אַרְעָךְ אַבְקָא וְעַפְרָא מִן שְׁמַיָא יֵחוּת עֲלָךְ עַד דְתִשְׁתֵּצֵי:
@70 יִתְּנִנָךְ יְיָ תְּבִיר קֳדָם סָנְאָךְ בְּאָרְחָא חֲדָא תִּפּוֹק לְוָתֵהּ וּבְשִׁבְעָא אָרְחָן תֵּעִרוֹק מִקָדָמוֹהִי וּתְהֵי לְזִיעַ לְכָל מַלְכְּוַת אַרְעָא:
@71 וּתְהֵי נְבִלְתָּךְ מְשַׁגְרָא לְמֵיכַל לְכָל עוֹפָא דִשְׁמַיָא וְלִבְעִירַת אַרְעָא וְלֵית דְמָנִיד:
@72 יִמְחִנָךְ יְיָ בְּשִׁחֲנָא דְמִצְרַיִם וּבִטְּחוֹרִין וּבְגַרְבָּא וּבַחֲרִיס יַבִּישׁ דִי לָא תִכּוּל לְאִתַּסָאָה:
@73 יִמְחִנָךְ יְיָ בְּטַפְשׁוּתָא וּבְסַמְיוּתָא וּבְשַׁעֲמָמוּת לִבָּא:
@74 וּתְהֵי מְמַשֵׁשׁ בְּטִּהֲרָא כְּמָא דִי מַשֵׁשׁ עַוִירָא בְּקַבְלָא וְלָא תַצְלַח יָת אָרְחָתָיךְ וּתְהֵי בְּרַם עָשִׁיק וְאָנִיס כָּל יוֹמַיָא וְלֵית דְפָרִיק:
@75 אִתְּתָא תֵירוֹס וּגְבַר אָחֳרָן יִשְׁכְּבִנַהּ בֵּיתָא תִבְנֵי וְלָא תֵיתֵב בֵּהּ כַּרְמָא תִצוֹב וְלָא תְחַלִנֵהּ:
@76 תּוֹרָךְ יְהֵי נָכֵס לְעֵינָיךְ וְלָא תֵיכוּל מִנֵהּ חֲמָרָךְ יְהֵי אָנֵס מִקֳדָמָךְ וְלָא יְתוּב לָךְ עָנָךְ מְסִירִין לְבַעֲלֵי דְבָבָךְ וְלֵית לָךְ פָּרִיק:
@77 בְּנָיךְ וּבְנָתָיךְ מְסִירִין לְעַמָא אָחָרָן וְעֵינָךְ חֲזָן וִיסוּפָן בִּגְלָלְהֵן כָּל יוֹמָא וְלֵית חֵילָא בִּידָךְ:
@78 אִבָּא דְאַרְעָךְ וְכָל לֵאוּתָךְ יֵכוּל עַמָא דִי לָא יְדַעַתְּ וּתְהֵי בְּרַם עָשִׁיק וּרְעִיעַ כָּל יוֹמַיָא:
@79 וּתְהֵי מִשְׁתַּטֵה מֵחֵזוּ עֵינָיךְ דִי תֶחֱזֵי:
@80 יִמְחִנָךְ יְיָ בְשִׁחֲנָא בִישָׁא עַל רְכֻבַיָא וְעַל שָׁקַיָא דִי לָא תִכּוּל לְאִתַּסָאָה מִפַּרְסַת רַגְלָךְ וְעַד מוֹחָךְ:
@81 יַגְלֵי יְיָ יָתָךְ וְיָת מַלְכָּךְ דִי תְקִים עֲלָךְ לְעַם דִי לָא יְדַעַתְּ אַתְּ וְאַבָהָתָיךְ וְתִפְלַח תַּמָן לְעַמְמַיָא פָּלְחֵי טַעֲוָתָא אָעָא וְאַבְנָא:
@82 וּתְהֵי לְצָדוּ לִמְתַל וּלְשׁוֹעֵי בְכֹל עַמְמַיָא דִי יִדְבְּרִנָךְ יְיָ לְתַמָן:
@83 בַּר זְרַע סַגִי תַּפֵּק לְחַקְלָא וּזְעֵר תִּכְנוֹשׁ אֲרֵי יַחְסְלִנֵהּ גוֹבָא:
@84 כַּרְמִין תִּצוּב וְתִפְלַח וְחַמְרָא לָא תִשְׁתֵּי וְלָא תִכְנוֹשׁ אֲרֵי תֵיכְלִנֵהּ תֹּלַעְתָּא:
@85 זֵיתִין יְהוֹן לָךְ בְּכָל תְּחוּמָךְ וּמִשְׁחָא לָא תְסוּךְ אֲרֵי יִתְּרוּן זֵיתָיךְ:
@86 בְּנִין וּבְנָן תּוֹלִיד וְלָא יְהוֹן לָךְ אֲרֵי יְהָכוּן בְּשִׁבְיָא:
@87 כָּל אִילָנָךְ וְאִבָּא דְאַרְעָךְ יַחְסְנִנֵהּ סַקָאָה:
@88 תּוֹתַב עָרֵל דִי בֵינָךְ יְהֵי סְלִיק עֵיל מִנָךְ לְעֵלָא לְעֵלָא וְאַתְּ תְּהֵי נָחֵת לְתַחְתָּא לְתַחְתָּא:
@89 הוּא יוֹזְפִנָךְ וְאַתְּ לָא תוֹזְפִנֵהּ הוּא יְהֵי לְתַקִיף וְאַתְּ תְּהֵי לְחַלָשׁ:
@90 וְיֵיתוּן עֲלָךְ כָּל לְוָטַּיָא הָאִלֵין וְיִרְדְפֻנָךְ וְיִדְבְּקֻנָךְ עַד דְתִשְׁתֵּצֵי אֲרֵי לָא קַבֶּלְתָּא לְמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר פִּקוּדוֹהִי וּקְיָמוֹהִי דִי פַקְדָךְ:
@91 וִיהוֹן בָּךְ לְאָת וּלְמוֹפֵת וּבִבְנָיךְ עַד עֳלָם:
@92 חֳלָף דִי לָא פְלַחְתָּא קֳדָם יְיָ אֱלָהָךְ בְּחֶדְוָא וּבְשַׁפִּירוּת לִבָּא מִסְגֵי כֹּלָא:
@93 וְתִפְלַח יָת בַּעֲלֵי דְבָבָךְ דִי יְגָרִנֵהּ יְיָ בָּךְ בְּכַפְנָא וּבְצַחוּתָא וּבְעַרְטִּלְיָתָא וּבַחֲסִירוּת כֹּלָא וְיִתֵּן נִיר פַּרְזְלָא עַל צַוְארָךְ עַד דִישֵׁיצֵי יָתָךְ:
@94 יַיְתִי יְיָ עֲלָךְ עַם מֵרָחִיק מִסְיָפֵי אַרְעָא כְּמָא דִי מִשְׁתְּדִי נִשְׁרָא עַמָא דִי לָא תִשְׁמַע לִישָׁנֵהּ:
@95 עַם תַּקִיף אַפִּין דִי לָא יִסַב אַפִּין לְסָבָא וְעַל יָנְקָא לָא מְרַחֵם:
@96 וְיֵיכוּל וַלְדָא דִבְעִירָךְ וְאִבָּא דְאַרְעָךְ עַד דְתִשְׁתֵּצֵי דִי לָא יַשְׁאַר לָךְ עִבוּרָא חַמְרָא וּמִשְׁחָא בַּקְרֵי תוֹרָיךְ וְעֶדְרֵי עָנָךְ עַד דְיוֹבֵד יָתָךְ:
@97 וְיָעֵק לָךְ בְּכָל קִרְוָיךְ עַד דְיִכְבַּשׁ שׁוּרָיךְ רָמַיָא וּכְרִיכַיָא דִי אַתְּ רָחֵץ לְאִשְׁתֵּזָבָא בְּהֵן בְּכָל אַרְעָךְ וְיָעֵק לָךְ בְּכָל קִרְוָיךְ בְּכָל אַרְעָךְ דִי יְהַב יְיָ אֱלָהָךְ לָךְ:
@98 וְתֵיכוּל וַלְדָא דִמְעָךְ בְּשַׂר בְּנָיךְ וּבְנָתָיךְ דִי יְהַב לָךְ יְיָ אֱלָהָךְ בִּצְיָרָא וּבְעַקְתָא דְיָעֵק לָךְ סַנְאָךְ:
@99 גַבְרָא דְרַכִּיךְ בָּךְ וְדִמְפַנַק לַחֲדָא תַּבְאֵשׁ עֵינֵהּ בְּאָחוּהִי וּבְאִתַּת קְיָמֵהּ וּבִשְׁאָר בְּנוֹהִי דִי יַשְׁאַר:
@100 מִלְמִתַּן לְחַד מִנְהוֹן מִבְּשַׂר בְּנוֹהִי דִי יֵיכוּל מִדְלָא אִשְׁתָּאַר לֵהּ כֹּלָא בִּצְיָרָא וּבְעַקְתָא דִי יָעֵק לָךְ סָנְאָךְ בְכָל קִרְוָיךְ:
@101 דְרַכִּיכָא בָךְ וְדִמְפַנְקָא דִי לָא נַסִיאַת פַּרְסַת רַגְלַהּ לַאֲחָתָא עַל אַרְעָא מִמְפַנְקוּ וּמֵרַכִּיכוּ תַּבְאֵשׁ עֵינַהּ בִּגְבַר קְיָמַהּ וּבִבְרַהּ וּבִבְרַתַּהּ:
@102 וּבִזְעֵר בְּנָהָא דְיִפְּקוּן מִנַהּ וּבִבְנָהָא דִי תְלִיד אֲרֵי תֵיכְלִנוּן בַּחֲסֵירוּת כֹּלָא בְּסִתְרָא בִּצְיָרָא וּבְעַקְתָא דִי יָעֵק לָךְ סָנְאָךְ בְּקִרְוָיךְ:
@103 אִם לָא תִטַר לְּמֶעְבַּד יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא דִכְתִיבִין בְּסִפְרָא הָדֵין לְמִדְחַל יָת שְׁמָא יַקִירָא וּדְחִילָא הָדֵין יָת יְיָ אֱלָהָךְ:
@104 וְיַפְרַשׁ יְיָ יָת מְחָתָךְ וְיָת מָחַת בְּנָיךְ מָחָן רַבְרְבָן וּמְהֵימְנָן וּמַכְתְּשִׁין בִּישִׁין וּמְהֵימְנִין:
@105 וְיָתֵב בָּךְ יָת כָּל מַכְתְּשֵׁי מִצְרַיִם דִי דְחֶלְתָּא מִקֳדָמֵיהוֹן וְיִדְבְּקוּן בָּךְ:
@106 אַף כָּל מְרַע וְכָל מָחָא דִי לָא כְתִיבִין בְּסִפְרָא דְאוֹרַיְתָא הָדָא יַיְתִנוּן יְיָ עֲלָךְ עַד דְיִשְׁתֵּצָךְ:
@107 וְתִשְׁתַּאֲרוּן בְּעַם זְעֵר חֳלָף דִי הֲוֵיתוּן כְּכוֹכְבֵי שְׁמַיָא לְמִסְגֵי אֲרֵי לָא קַבֶּלְתָּא לְמֵימְרָא דַיְיָ אֱלָהָךְ:
@108 וִיהֵי כְּמָא דְחַדֵי יְיָ עֲלֵיכוֹן לְאוֹטָבָא יָתְכוֹן וּלְאַסְגָאָה יָתְכוֹן כֵּן יֶחֱדֵי יְיָ עֲלֵיכוֹן לְאוֹבָדָא יָתְכוֹן וּלְשֵׁצָאָה יָתְכוֹן וְתִטַלְטְלוּן מֵעַל אַרְעָא דְאַתְּ עָלֵל לְתַמָן לְמֵירְתַהּ:
@109 וִיבַדְרִנָךְ יְיָ בְּכָל עַמְמַיָא מִסְיָפֵי אַרְעָא וְעַד סְיָפֵי אַרְעָא וְתִפְלַח תַּמָן לְעַמְמַיָא פָּלְחֵי טַעֲוָתָא דִי לָא יְדַעְתְּ אַתְּ וַאֲבָהָתָךְ אָעָא וְאַבְנָא:
@110 וּבְעַמְמַיָא הָאִנוּן לָא תְנוּחַ וְלָא יְהֵי מְנָח לְפַרְסַת רַגְלָךְ וְיִתֵּן יְיָ לָךְ תַּמָן לֵב דָחֵל וְחַשְׁכַת עַיְנִין וּמַפְּחַן נְפָשׁ:
@111 וִיהוֹן חַיָיךְ תְּלָן לָךְ מִקָבֵל וּתְהֵי תָוֵה לֵילְיָא וִימָמָא וְלָא תְהֵימִין בְּחַיָיךְ:
@112 בְּצַפְרָא תֵימַר מָן יִתֵּן רַמְשָׁא וּבְרַמְשָׁא תֵימַר מָן יִתֵּן צַפְרָא מִתַּוְהוּת לִבָּךְ דִי תְהֵי תָוֵה וּמֵחֵזוּ עֵינָיךְ דִי תְהֵי חָזֵי:
@113 וְיָתֵיבִנָךְ יְיָ מִצְרַיִם בִּסְפִינָן בְּאָרְחָא דִי אֲמָרִית לָךְ לָא תוֹסֵף עוֹד לְמֶחְזְיַהּ וְתִזְדַבְּנוּן תַּמָן לְבַעֲלֵי דְבָבָךְ לְעַבְדִין וּלְאַמְהָן וְלֵית דְקָנֵהּ:
@114 אִלֵין פִּתְגָמֵי קְיָמָא דִי פַקִיד יְיָ יָת מֹשֶׁה לְמִגְזַר עִם בְּנֵי יִשְׂרָאֵל בְּאַרְעָא דְמוֹאָב בַּר מִקְיָמָא דִי גְזַר עִמְהוֹן בְּחֹרֵב:
@115 וּקְרָא מֹשֶׁה לְכָל יִשְׂרָאֵל וַאֲמַר לְהוֹן אַתּוּן חֲזֵיתוּן יָת כָּל דִי עֲבַד יְיָ לְעֵינֵיכוֹן בְּאַרְעָא דְמִצְרַיִם לְפַרְעֹה וּלְכָל עַבְדוֹהִי וּלְכָל אַרְעֵהּ:
@116 נִסִין רַבְרְבִין דִי חֲזָאָה עֵינָךְ אָתַיָא וּמוֹפְתַיָא רַבְרְבַיָא הָאִנוּן:
@117 וְלָא יְהַב יְיָ לְכוֹן לִבָּא לְמִדַע וְעַיְנִין לְמֶחֱזֵי וְאֻדְנִין לְמִשְׁמַע עַד יוֹמָא הָדֵין:
@118 וְדַבָּרִית יָתְכוֹן אַרְבְּעִין שְׁנִין בְּמַדְבְּרָא לָא בְלִיאַת כְּסוּתְכוֹן מִנְכוֹן וּמְסָנָךְ לָא:עַדוֹ מֵעַל רַגְלָךְ:
@119 לַחְמָא לָא אֲכַלְתּוּן וַחֲמַר חֲדַת וְעַתִּיק לָא שְׁתֵיתוּן בְּדִיל דְתִדְעוּן אֲרֵי אֲנָא יְיָ אֶלָהֲכוֹן:
@120 וַאֲתֵתוּן לְאַתְרָא הָדֵין וּנְפַק סִיחוֹן מַ לְכָּא דְחֶשְׁבּוֹן וְעוֹג מַ לְכָּא דְמַתְנָן לָקֳדָמוּתָנָא לַאֲגָחָא קְרָבָא וּמְחוֹנוּן:
@121 וּנְסִבְנָא יָת אַרְעֲהוֹן וִיהָבִנַהּ לְאַחֲסָנָא לְשִׁבְטָּא דִרְאוּבֵן וּלְשִׁבְטָא דְגָד וּלְפַלְגוּת שִׁבְטָא דִמְנַשֶׁה:
@122 וְתִטְרוּן יָת פִּתְגָמֵי קְיָמָא הָדָא וְתַעְבְּדוּן יָתְהוֹן בְּדִיל דְתִצְלְחוּן יָת כָּל דִי תַּעְבְּדוּן: פפפ:

@1 **והיה כי תבא אל הארץ**. אמר **והיה** לשון שמחה, להעיר שאין לשמוח אלא בישיבת הארץ על דרך אומרו (תהלים קכ''ו) אז ימלא שחוק פינו וגו':
@1 **אשר ה' אלהיך נותן לך נחלה וירשתה וגו'**. צריך לדעת מה היא גזירת הכתוב, אם ולקחת וגו' הוה ליה למימר תקח מראשית כיון שהוא התחלת הציווי, ונראה שכוונת הכתוב היא שיצו ה' ד' מצות, אחד שידע בלבו כי לא בכוחו ולא בעוצם גבורתו בא לרשת הארץ אלא מתת ה', והוא אומרו אשר ה' אלהיך נותן לך, ודקדק לומר ה' **אלהיך** להעיר שעל מנת שיקבל אלהותו עליו הוא נותן, ב' להוריש הארץ מיושביה הגם שיש לו דבר המספיק לו בארץ אף על פי כן יגרש אויבי ה' מארצו, והוא אומרו **וירשתה** שלישית ישיבת הארץ שהיא מצוה בפני עצמה כמו שמצינו כמה הפליגו רבותינו ז''ל (כתובות קי''א.) במצות ישיבת הארץ, רביעית הבאת הבכורים כאומרו **ולקחת** וגומר:
@2 **מראשית**. פירוש שאם בכרו הרבה כאחת אינו חיב להביא כל ראשית אלא אשר יחפוץ מהם, ומה שאמרו ז''ל (ביכורים פ''א מ''ו) שאין להביא אלא מז' המינים נלמד הדבר בגזרה שוה נאמר כאן ארץ וגו', (מנחות פ''ד:) ואומרו **כל פרי** פירוש כל הפירות ששבחתי לך בהם ה א רץ:
@2 **אשר ה' אלהיך נותן לך**. פירוש לפי ששייר ה' לו חלק בארץ והוא שנת השמיטה (ויקרא כ''ה ד') דכתיב ובשנה השביעית וגו' שבת לה', לזה בא דברו הטוב שאינו מצוה אלא על זמן הנתינה לך שהם ו' שנים אבל שנת השמיטה אין בה הבאת ביכורים לפי שאינם שלו אלא מופקרת לכל:
@3 **נשבע וגו' לתת לנו**. למעט הגר שאינו קורא (ביכורים פ''א) ולא מיעטו אלא בקריאה ולא בהבאה:
@5 **וענית ואמרת**. אמר **וענית** יש מפרשים לשון התחלה וכמו (איוב ג') ויען איוב, ואפשר שהוא עוני כאדם פחות שקבל טובה גדולה ממלך שמעני עצמו לפניו בלב נשבר כמו כן הוא יכניע עצמו לפני ה', ויאמר ארמי אובד אבי כי אבינו היה אובד ותועה וגולה במצרים במתי מעט וגו', ויוציאנו ה' ממצרים ויביאנו וגו', וכנגד מאמר זה שיש בו עילוי וחשיבות אמר **ואמרת**, וכיוצא בזה אמרו רבותינו ז''ל (פסחים קט''ז.) בענין הגדת פסח מתחיל בגנות ומסיים בשבח:
@5 **והצצתי** בפרשה זו שרומזת גם כן ביאת ארץ העליונה, ואמר **והיה כי תבא** שאין ראוי לאדם לשמוח אלא כשיבא לארץ העליונה על דרך אומרו (משלי ל''א) ותשחק ליום אחרון, כי שמחת עוה''ז אינה אלא הבל ורעות רוח, וחזר ופירש על איזה ארץ מדבר ואמר **אשר ה' אלהיך נותן לך נחלה** כי לזו יקרא נחלת עולם, ודקדק לומר **נותן לך**, כי בערך מה ששוה עולם העליון כל מה שיסגל אדם בעדו לא יגיע לחלק מאלף אלפים משוויו, ולזה אמר נותן לך בתורת מתנה, ולצד שצריך האדם לטרוח בעולם הזה לקיים תורה ומצות לז''א וירשתה, ואמר **וישבת בה** על דרך אומרם (ברכות ל''ה.) צדיקים יושבים ועטרותיהם בראשיהם, ואומרו **ולקחת** וגו' על דרך אומרו בס' הזוהר (ח''ב נ''ט) כי כל אשר יעשה האדם מהמצות ומעשים טובים בעודו חי מתקבץ על יד על יד עד יום נסיעתו ובהם מקבל פני המלך כדרך אומרו (ישעי נ''ח) והלך לפניך צדקך, והוא אומרו **ולקחת מראשית כל פרי** וגו' פירוש לא יקח בידו להקביל פני ה' אלא מדברים המובחרים שעשה בעולם הזה:
@5 **עוד** רמז אל התורה שנקראת ראשית (ב''ד פ''א), ואומרו **אשר ה' אלהיך נותן לך** יתבאר על דרך אומרם ז''ל (ברכות ל''ה.) כתיב לה' הארץ ומלואה וכתיב והארץ נתן לבני אדם לא קשיא כאן קודם ברכה כאן לאחר ברכה ע''כ, הרי שאחר שיעשה האדם מה שציוהו ה' נחשב הדבר שבאמצעותו עשה המעשה שהוא נתון לו במתנה, שזולת זה כל מעשה האדם אין לנו בו יתרון כי לפי שמפעלו כלו הוא באמצעות עולם שהוא בו ולה' הארץ ומלואה, לזה אמר אשר ה' אלהיך נותן לך:
@5 **ואומרו ושמת בטנא**. ירמוז שצריך כל מפעלות הטובות שעשה יהיו על פי דבריהם, כאומרו (לעיל י''ז י''א) על פי התורה אשר יורוך ועל המשפט וגו', והתורה והמשפטים ביארו אותם חכמים בס' מסכתות כמנין טנא, שזולת זה הגם שיעשה כל מצות שבעולם ישרף הוא והם, ואומרו **והלכת אל המקום** וגו' לפי שבעלית הנפש לעולם העליון לא תלך תכף ומיד להקביל פני ה' עד שיכין עצמו בפרוזדור, ויש שמתעכבים עד שבעה ימים, או חודש, או ימים, כאמור בס' הזוהר (ח''א פ''א), ואחר כך עולה לגן עדן העליון הנקרא צרור החיים, והוא המקום אשר יבחר ה' לשכן שמו שם:
@5 **ואומרו ובאת אל הכהן**. על דרך אומרם ז''ל (חגיגה י''כ.) כי מיכאל עומד לכהן לפני ה' להקריב הנפשות לפני אלהי עולם, ואליו יאמר כדברים האלה הגדתי היום וגו', ואומרו **אשר יהיה בימים ההם** יתבאר על פי דבריהם שאמרו שישתנה הכהן העומד שם, צא ולמד מה שאמרו בזוהר חדש (פ' לד) בענין מיכאל אימתי זכה להיות במצב זה שהוא מעת שהעלה נפשו של דוד לג''ע העליון אחר שבנה שלמה בית המקדש וכו', הרי שלפעמים ישתנה הכהן, לז''א אשר יהיה בימים ההם, ואמרת אליו הגדתי היום לה' כי באתי אל הארץ היא ארץ שממנה בא, ואמר **נשבע ה' לתת לנו** היא ארץ ישראל שבאמצעותה ישיגו קיום התורה ומצות ומעשים טובים, ואמרו **ולקח הכהן הטנא מידך** פירוש שלא יקבל שר עליון אלא הבא בידו מיוסד על דברי תורה שבעל פה הרמוז בתיבת טנא כמו שכתבנו, והניחו לפני וגו':
@5 **ואומרו וענית ואמרת וגו'**. פירוש לפי שכל אשר יעשה האדם מהטובות בעה''ז אין די לרצות מלך עליון, צא ולמד ממה שאמרו רבותינו ז''ל (ערובין י''ז.) אם יבא במשפט עם אברהם יצחק ויעקב אינן יכולין לעמוד לפניו כי מה יצדק אנוש, וכתיב (איוב ד') אם מעושהו יטהר גבר, לזה אמרה תורה שיתן תשובה לה' והתנצלות על אשר לא עשה רצונו יתברך כמצטרך, והוא אומרו **וענית ואמרת לפני ה'**, **ארמי אובד אבי** ארמי זה יצה''ר שהוא רמאי גדול כאומרו (בראשית ג' א') והנחש היה ערום, שמרמה הבריות לאבדם, והוא אומרו **אובד אבי** פירוש אדם הראשון על דרך אומרו (ישעי' מ''ג כ''ז) אביך הראשון חטא, ואבדו וגרם מיתה לו ולדורות הבאים אחריו והשריש בכל הנפשות חלק הרע, והוא סוד ערלה הדבוקה באדם מבטן ומהריון, עוד ירצה באומרו **אובד אבי** על דרך אומרו (תהלים י''ד) אמר נבל בלבו אין אלהים:
@5 **עוד** ירצה באומרו **אבי** שהיא הנשמה שכל מועצותיו של השטן לאבד הנשמה והנשמה נקראת אב כאומרם בזוהר פרשת לך לך (ע''ו.) והוא הוא המונע האדם מעשות חיובו בעבודת ה', ולא זו בלבד אלא וירד מצרימה פירוש המקום שבא בו היצר שהוא גופו של אדם הוא מצריו של היצר הקרובים אליו בסוד (ישעי ס''ה) ונחש עפר לחמו, וחפצים באשר יחפוץ מדברי עולם הזה ומטעמיו אשר התעיב ה', כי ד' יסודות שבו הן היום אחר חטא האדם נגשמו ונטמאו שלסיבה זו גזר ה' מיתה להאדם, ובזה נשמעים דבריו ופיתוייו ליסודי האדם, גם יקרא הגוף מצרים לפי שמצר לנפש בתאוותיו, ואומרו **ויגר שם** כי בתחלה נכנם כגר כאומרו (ש''ב י''ב) ויבא הלך וגו', (סוכה נ''ב:) **במתי מעט** פירוש בכחות מועטים, ואח''כ מתרבים כוחותיו על ידי האדם עצמו והוא אומרו **ויהי שם לגוי גדול עצום**, **ורב** בסוד (תהלים כ''ה) וסלחת לעוני כי רב הוא, ופירוש הרב האר''י ז''ל שחוזר אל המפתה כי רב הוא, והראיה שצוה ה' ביום הכיפורים גורל א' לה' וגורל א' לעזאזל:
@6 **ואומרו וירעו אותנו המצרים וגו'**. פירוש שבאמצעות יסודות האדם גרמו גם לנפש להרשיע כמותם, והוא אומרו **וירעו אותנו** פירוש עשו אותנו רעים כמותם כי המזג כשיסריח ימשוך אליו רצון הנפש, ואומרו **ויענונו** זה אפיסת כח הלוחם כנגד היצה''ר, צא ולמד ממעשה רב עמרם חסידא (קידושין פ''א.) שלא היה בו כח להתעצם כנגד המחטיא עד שקרא נורא בי עמרם וכו', ואומרו **ויתנו עלינו עבודה קשה** פירוש שלא נהג היצר בדרך זה בעתים מרוחקים אלא תמיד בכל שעה ובכל רגע מתגבר על האדם ולזו יקרא עבודה קשה, עוד נתכוון על פי דבריהם ז''ל (שם ל:) שאמרו בכל יום מתחדש היצר על האדם בתגבורת חדש וכנגד זה אמר **עבודה קשה** כל אלה הדברים יאמר עבד ישראל לפני הבורא להתנצל על מנחה קטנה:
@7 **ואומרו ונצעק אל ה'** כאן רמז שצריך האדם להתפלל לה' בכל יום שיצילהו מיצר הרע, והוא אומרו **ונצעק אל ה'** וגו', ואומרו **וישמע ה' את קולנו** וגו' פירוש הגם שה' הוא שברא יצר הרע לבחון האדם בעבודת בוראו אף על פי כן כשצועקים אליו שומע קולם מטעם שראה את הרשום שהוא ענינו ועמלנו ולחצנו, העוני הוא אפיסת כח הלוחם שאין כח בנו המספיק להלחם בו לגרשו ממנו, העמל הוא שאנו צריכין לעמול במלחמתו, הלחץ הוא הדחק שדוחק היצר את האדם לחטוא בעל כרחו, ולג' סיבות שמע ה' את קולנו, עוד ירצה ענינו זה העניות הנסבך עם לומדי תורה כאומרם ז''ל (מררש תהלים ה') שאמרה תורה מפני מה בני עניים, והגם שימצא בן תורה שאין שבט עוני עליו אף על פי כן יתנהג במדת עוני כאומרם (אבות פ''ו) כך היא דרכה של תורה וגו', ואת עמלינו על דרך אומרם (בדכות י''ז.) אשרי מי שעמלו בתורה וגו', ומה גם בדורות האחרונים שרב עמלה להוציא לאור משפט א' והלכה אחת, ואת לחצנו כי כל הנסמך לתורה רבו לוחציו ועיני כל אליו ישברו:
@8 (ח~ט) **ואומרו ויוציאנו ה' ממצרים**. זו הצלת יצר הרע וכוחותיו המצירים אותנו, כי הוא המציל מיצר הרע כאומרם ז''ל (קידושין ל':) שלולי שה' עוזר לאדם כנגד יצר הרע אין אדם שליט להנצל ממנו דכתיב צופה רשע זה יצר הרע לצדיק להמיתו ה' לא יעזבנו בידו, ואומרו **ביד חזקה** וגו' רמז לדברים שבאמצעותם יצילהו ה' וכו' והוא על דרך אומרם ז''ל (שם) אמר הקב''ה בראתי לכם יצר הרע בראתי לו תבלין שהיא התורה, והוא אומרו **ויוציאנו ה'** וגו', **ביד חזקה** זו תורה שנתנה מימינו של הקב''ה דכתיב (לקמן ל''ג ב') מימינו אש דת למו, גם נתנה בגבורות מתוך האש:
@8 **ואומרו ובזרוע נטויה** וגו' רמז לג' דברים שבאמצעותם ניצול אדם מיצר הרע כאומרם ז''ל (מנחות מ''ג:) כל מי שיש לו תפילין בזרועו וציצית בבגדו ומזוזה בפתחו לא במהרה הוא חוטא, כנגד תפילין בזרועו אמר **ובזרוע נטויה** שמצות תפילין בזרוע, ואמר **ובמורא גדול** כנגד תפילין של ראש, וכנגד ציצית אמר **ובאותות** כי מצות ציצית הוא סימן לנו שאנו עבדי הקב''ה וכמו שפירשנו בפרשת ציצית (פ' שלח) גם תקרא כן ברמז התכלת שבו כמו שכתב רמב''ן (פ' שלח) שרומז אל מדה הכוללת שנקרא אותות, וכנגד המזוזה אמר **ובמופתים** כמשמעה, גם תקרא המזוזה מופת להיותה מופת לזוז מות מישראל כאומרם בספר הזוהר (ח''ג רס''ה) שכמה כתות הקליפות נרתעים בראותם שם שדי על פתח בית ישראל:
@8 **עוד** אפשר שכל הכתוב ירמוז אל התורה שבה ינצל אדם מיצר הרע ומתאוות עולם הזה, ואמר ה' ענינים כנגד ה' חומשי תורה, **ביד חזקה** כנגד ספר בראשית כי שם נאמר מעשה ידי יוצר אשר כוננו ידיו עולם ומלואו, ואמר **ובזרוע נטויה** כנגד ספר שמות כי בו חשף את זרועו והרא' גבורותיו במעשה מצרים ובים ובנתינת התורה, ואמר **ובמורא גדול** כנגד ויקרא כי שם צוה מעשה [עבודת] המשכן ושכונת שכינתו וצוה על מורא המקום וקידש הבית בב' גדולי ישראל ולזה יחס לספר זה מורא גדול, ואמר **ובאותות** כנגד ספר חומש הפקודים על שם (במדבר ב' ב') איש על דגלו באותות, ואמר **ובמופתים** כנגד ספר דברים כי בו דבר משה אל כל ישראל והוכיח במופתים על פחזותם ועל טוב ה' וחסדו עמהם, והוכיח כי לא שלם ה' להם כמעשיהם הרעים וגבר עליהם חסדו, גם בו נאמר מופתי הנביאים שבהם יצדיקו הנביא, ואומרו **ויביאנו אל המק ום הזה** מדבר על עולם העליון שהנשמה בו, והנה אין הנשמה מגעת לדבר כל הדברים האלה אלא אחר עלייתה לעולם העליון שנקרא גן עדן של מעלה אחר שכבר שבעה ימים בגן עדן שלמטה, ולזה כנגד עמידתה לפני ה' לדבר הדברים האלו אומר:
@8 **ויביאנו אל המקום הזה** כי עמידת הנפש שם לבד יש לה בו שעשוע גדול וכנגד גן עדן שלמטה שכבר זכה בו אמר **ויתן לנו את הארץ הזאת ארץ זבת חלב ודבש** על דרך אומרו (שה''ש ד') דבש וחלב תחת לש ונך:
@10 (י~יא) **ואומרו ועתה הנה**. פירוש אומרו ועתה לשון תשובה ששב לפני ה' על פרטי דקדוקי המצות, והגם שהכתוב מדבר במי שכבר זכה בגן עדן שלמטה אף על פי כן כדי לזכות לגדר עליון ידקדקו עליו ביותר, והוא סוד המשפט שישפוט ה' לעתיד לבא בעמק יהושפט (מדרש תהלים ח') שממנו פחד ורהב שמואל כשהעלתו בעלת אוב (חגיגה ד:):
@10 **ואומרו הנה הבאתי את ראשית וגו' אשר נתת לי**. כמו שפירשתי למעלה במאמר אשר ה' אלהיך נותן לך:
@10 **ואומרו והשתחוית לפני ה'**. בזה העיר רוח חיים בטובה המופלאת בעדות המופלג אשר יזכו אליו הצדיקים, והוא שתתקרב נפש הצדיק לפני אור הנערב ותשתחוה לפניו באין מסך מבדיל אשרי נפש אדם שתגיע לגדר מופלג כזה, והוא אומרו **והשתחוית לפני ה' אלהיך** שם תכיר הנפש אלהיה, ואמר סמוך לזה **ושמחת בכל הטוב** על דרך אומרו (תהלים קמ''ה) טוב ה', ולהעירך על זה אמר בכל הטוב פירוש דבר הכולל כל הטוב ואין זה אלא הקב''ה שהוא מקור הטוב, **אשר נתן לך** פירוש כי דבר זה אין ערך אליו אלא מתנת חנם:
@10 **ואמר לך**, לשלול זולתו לא מלאך ולא שרף יזכה לזה, גם ירמוז במאמר **בכל הטוב** אל התורה כאומרם ז''ל (ברכות ה'.) ואין טוב אלא תורה, שאם היו בני אדם מרגישין במתיקות ועריבות טוב התורה היו משתגעים ומתלהטים אחריה ולא יחשב בעיניהם מלא עולם כסף וזהב למאומה כי התורה כוללת כל הטובות שבעולם:
@10 **ואומרו ולביתך**. כי לא לנשמה לבד יגיע הטוב אלא גם לבית הנשמה שהיא רוח ונפש שהם משכן הנשמה כל א' יתעדן כפי יכלתו:
@10 **ואומרו והלוי**. יתבאר על פי דבריהם ז''ל שאמרו בזוהר (ח''ב צ''ד) וזה לשונם זכה יתיר יהבין ליה נשמתא וכו' זכה יתיר יהבין ליה נשמתא מאור אצילות וכו' ע''כ, ולבחינה זו יקרא הכתוב לוי לפי שמתלות עם האדם מחדש:
@10 **ואומרו והגר**. יתבאר על פי דבריהם ז''ל (זוהר ח''ג רי''ז.) שאמרו כי כשיגיע ליד אדם מצוה מאותם מצות שאינם נוהגות תמיד אותם הנשמות שכבר נסתלקו מהעולם והם חסרי מצוה זו באים וגרים עם העושה המצוה על זה הדרך קרובים לשכר ורחוקים מן ההפסד כאמור באורך בדברי המקובלים, וכנגד בחינה זו אמר והגר אשר בקרבך:
@15 **השקיפה ממעון וגו'**. צריך לדעת למה כפל לומר **ממעון** וגו' **מן השמים**, ואם לכנות שם מקומו יתברך בלשון קדושה היה לו לומר על זה הדרך השקיפה ממעון וגו' השמים, ונראה שהכתוב יעיר סוד אחד והוא כי האדון ברוך הוא הכין ב' השפעות למעלה, א' השפעת הרוחניות שהם הנפשות הטהורות, ואחד השפעת הטוב לחיות הנבראים שהוא מזון לכל, ושנים אלו יקראו להם רבותינו ז''ל (זוה''ק) זיווג, שכל שיש בבחינת משפיע ובחינת נשפע יתכנו בשם זיווג, ואמרו המקובלים שמיום שנחרב הבית נפסק השפעת הנשמות ולא נשאר אלא השפעת חיות העולמות שהוא מוכרח לקיום העולמות, והוא אומרו **השקיפה ממעון קדשך** כנגד השפעת הנשמות, והשקפה זו היא עליונה במקום גבוה הנקרא קודש, וכבר גילו המקובלים (זוהר ח''ב קכ''א.) מה בין הדרגת קודש להדרגת קדוש כי קדוש למעלה והמשכיל יבין, וכנגד השפעת חיות העולמות אמר מן השמים זה זיווג למטה מהראשון, ואמר כנגד מאמר השקיפה וברך את עמך ופירשו רבותינו ז''ל (מע''ש פ''ה מי''ג) בבנים ובנות, וזה יצדיק פירושינו שעל זווג הנשמות הוא אומר, וכנגד מאמר את השמים אמר ואת האדמה שהיא ברכת המזון ונכון:
@16 **היום הזה וגו'**. וכי היום הוא מצוה והלא כבר צוה בהר סיני, ורש''י ז''ל פירוש בכל יום יהיו בעיניך חדשים. ונראה שכונת הכתוב היא על זה הדרך לפי שכל התורה צוה אותה ה' בהר סיני בין דברים שיש בהם קום עשה באותו זמן בין דברים שאינם בקום עשה אלא לאחר זמן כאותם האמורים בפרשה זאת בכורים ומעשרות שאינם נוהגים אלא בארץ, וצוה ה' אותם הגם שלא היה זמנם מטעם כדי ללמוד אותם ולקבל שכר על קבלתם, ואמר להם משה כי הן היום מצוה אותם לעשות החוקים האלה שהם בכורים ומעשרות שעד היום נצטוו ללמוד דיניהם לבד והיום הזה מצוה אותם לעשות כי הגיעו לארץ, ותיבת היום לאו דוקא אלא זכר זמן המוכן בשם היום הזה:
@17 **את ה' האמרת היום להיות וגו'**. אומרו **היום** יתבאר על דרך אומרם ז''ל (כתובות ק''י:) כל הדר בחוץ לארץ דומה כמי שאין לו אלוה ע''כ, והוא אומרו **את ה' האמרת היום** דוקא פירוש כיון שהיו בארץ המקודשת, והגם שעדיין היו בארץ סיחון ועוג עם כל זה כבר כתבנו שהיא מקודשת כיון שנכבשה כבוש רבים על פי נביא, וכמו שהוכחנו בפרשת מטות (ל''ב ג') ומעתה אין מקומה נחשב חוצה לארץ ולזה האמירו ה' להיות להם לאלהים, והוא אומרו להיות לך לאלהים:
@17 **עוד** ירצה על דרך אומרם ז''ל (זוהר ח''א ק''ח:) ששאר הארצות נמסרו ביד שרי מעלה מה שאין כן ארץ ישראל אין עליה שופט מבלעדי ה', והוא אומרו **את ה' האמרת היום** בכניסתך לארץ להיות לך לאלהים על דרך אומרו (תהלים י''ז) מלפניך משפטי יצא ולא יבא משפטינו לפני שר ושופט:
@17 **עוד** נתכוין לומר כי יאמירו ה' הגם כי יביאם במשפט לתת לאיש כדרכיו וכמעשיו הרעים, והוא אומרו **את ה' האמרת** וגו' **להיות לך לאלהים**, וידוע כי אלהים הוא מדת הדין אף על פי כן יאמיר ה' ויברך על הרעה מעין הטובה:
@17 **ואומרו וללכת בדרכיו**, פירוש הגם שלא צוה ה' ללכת בהם אף על פי כן כשיכירו בהם שהם דרכי ה' כל אשר הוא עושה יעשו כן בני ישראל, כגון ביקור חולים קבורת מתים וכדומה שמצינו לה' עושה אותם ילכו גם הם בדרכיו, **חקיו** הם מצות שאין בהם טעם, **מצותיו** הם מצות שהשכל גם כן מסכים עליהם, **משפטיו** הם דינים שמסר לשפוט בין איש ובין רעהו, **ולשמוע בקולו** זה תלמוד תורה, ודקדק לומר בקולו על דרך אומרם ז''ל (במד''ר פ' י''ד) וז''ל מנין לשומע מפי קטן וכו' כשומע מפי הגבורה דכתיב (לעיל ט''ו ה') אם שמוע תשמע בקול ה' אלהיך, וטעם שצוה על עסק התורה באחרונה, להעיר שהגם שהשיג אדם לדעת כל האמור וקיימו אף על פי כן לא יאמר מה לי ללמוד תורה אם לדעת מה יעשה ישראל הנה ידעתי וקיימתי כל דברי ה' אלא אף על פי כן חייב הכתוב תלמוד תורה, והוא אומרו אחר כל מה שחייב לעשות ולשמוע בקולו כי מצות תלמוד תורה היא מצוה בפני עצמה שאין זמן ליפטר ממנה עד יום מותו דכתיב (במדבד י''ט י''ד) זאת התורה אדם כי ימות באהל:
@18 **וה' האמירך וגו'**. אומרו **להיות לו לעם סגולה**, שהגם שתבא אומה אחרת ותטיב מעשיה ותשתדל להדבק בשכינה לא ישיגו מדרגת ישראל, ובחינה זו תקרא סגולה וזו היא גדולתם, ואומרו **כאשר דבר לך**, במעשה הר סיני דכתיב (שמות י''ט ה') והייתם לי סגולה מכל העמים:
@18 **או** ירצה שהגם שיהיה זמן שיכעיסו ישראל את הבורא אף על פי כן לא ימיר אותם באומה אחרת, ואומרו **כאשר דבר** כאומרם ז''ל (ברכות ז') בפסוק (שמות ל''ג ט''ז) ונפלינו אני ועמך, שבקש משה מה' שלא ישרה שכינתו על האומות, ופירשנוהו במקומו (חפץ ה') שהכוונה היא הגם שתכשיר מעשיה אומה מאומות וישראל עוברי רצונו והסכים ה' ודבר לעשות כדברי משה:
@18 **ולשמור כל מצותיו**. יש להעיר בדבר הלא דבר זה הוא מתנאי הכבוד שרשם במעשה ישראל לה' כמו שכתוב בפסוק את ה' האמרת ומה מקום להזכירו בדברים שמה' לישראל:
@18 **ואולי** כי תפארת ישראל היא מה שהעלה ורומם אותם בתת להם כל המצות, מה שלא עשה כן לראשונים שהגם שנתן מצותיו יתברך לאדם ולנח ולהאבות לא נתן אלא ב' ג' גרגרים אבל לישראל נתן שמירת כל מצותיו יתברך, ויש לך לדעת כי כל המצות אינם אלא שמירה מהתיעוב ומלכלוך הנפש ובהשלמת שמירת המצות יהיה האדם שלם מכל מום ומכל לכלוך:
@18 **ב')** ירצה כי ה' יחזק זרועות לשמור כל המצות, כי לא הכל זוכים לדבר זה הגם שיחפצו לשמור לא יזדמן לידם, ואם יזדמן לא תשיג ידם, ואם תשיג לחלק מהמצות לא תשיג לכל המצות, ואמר כאן כי ה' האמירם לשמור כל מצותיו:
@18 **ג')** ירצה על דרך אומרו (קהלת ח') שומר מצוה לא ידע דבר רע, ואמרו ז''ל (פסחים ח:) שלוחי מצוה אינם ניזוקין, והוא מאמר הכתוב כאן **ולשמור** פירוש ה' ישמור כל מצותיו לבל יצא מהם דבר תקלה:
@18 **ד')** ירצה להעירם בדבר שלא השיגו משה עצמו ע''ה הגם היותו בכלל עם סגולה, והוא על דרך אומרם ז''ל (סוטה י''ד.) בענין תפלת משה ליכנס לארץ וכי לאכול מפירותיה וגו' אלא אמר משה יש הרבה מצות שתלויות בארץ וכו' ע''כ, והוא מה שנתכוון לומר להם ראו מעלתכם שה' האמיר אתכם וגו' ולשמור כל מצותיו, ולזה דקדק לומר **האמירך היום** פירוש בזמן זה שאתה באים אל הארץ ושם תשמרו כל המצות, וזו מעלה שלא השיגה אפילו משה:
@18 **והנה** תמצא ו' מעלות בפסוק **את ה' האמרת**, א' להיות לך לאלהים, ב' ללכת בדרכיו, ג' לשמור חקיו, ד' ומצותיו, ה' ומשפטיו, ו' ולשמוע בקולו, כנגדם אמר ה' שש מעלות לכנסת ישראל, א' להיות לו לעם סגולה זה כנגד להיות לך לאלהים, ב' ולשמור כל מצותיו זה כנגד ללכת בדרכיו, ג' ד' וה' ולתתך עליון וגו' לתהלה ולשם לתפארת הם כנגד שמירת חקיו ומצותיו ומשפטיו, ו' ולהיותך עם קדוש לה' זה כנגד ולשמוע בקולו כי על ידי עסק התורה יתייחס להם שם זה של קדוש, ואומרו **כאשר דבר** דכתיב (שמות י''ט ו') ואתם תהיו לי וגו' וגוי קדוש אלה הדברים אשר תדבר אל בני ישראל:
@20 **ויצו משה וזקני ישראל**. טעם זכרון זקני ישראל כאן, נתכוון משה בזה מה שאמרו רבותינו ז''ל (ברכות י''ט:) שבמקום שיש חילול ה' אין חולקין כבוד לרב דכתיב (משלי כ''א ל') אין חכמה וגו' לנגד ה', והוא אומרו ויצו משה ולפניו שהוא רבן של ישראל עשה שגם הזקנים יצוו ויזהירו על הדבר לאמר שמור וגו', דקדק לומר **שמור** להעיר כי בדבר זה שהוא מצות לא תעשה (מכות י''ג:) הוא שאמרו אין חולקין כבוד לרב כידוע:
@22 **למען אשר תבא**. ראב''ע פירוש אם החלות לשמור מצותיו וזו מצוה ראשונה וכו', ורמב''ן פירש לרמוז אל התורה וכו', ואין הכתוב מתיישב לב' הפירושים, ויש להעיר עוד אומרו **כאשר דבר ה' אלהי אבותיך לך** שלא היה צריך לומר תיבת לך אחר שאמר אשר תבא אל הארץ כאשר וגומר הדבר מובן שאליהם הוא הדבר:
@22 **אכן** כוונת הכתוב לפי שקדם מאמר משה לישראל כי ביאת הארץ לא בזכות ישראל כאומרו (לעיל ט, ה,) לא בצדקתך וגו' אלא ברשעת הגויים וגו' ולמען הקים וגומר, לזה בא דברו כאן כי באמצעות המעשה האמור בענין תהיה ביאתם לארץ בזכות עצמם, וגזירת הכתוב היא תיבת לך האמור לבסוף, וזה שיעור הכתוב למען אשר תבא פירוש תהיה ביאתך לארץ אשר ה' אלהיך נותן לך כאשר וגו' לך פירוש למען שאתה ראוי ולא תצטרך לזכות ברית אבות והבן:
@33 **וענו הלוים**. פירוש והתחילו שהם יתחילו לדבר והעם יענו אחריהם אמן, ואונקלוס תרגום ויתיבון, ולדבריו וענו הלוים תשובה להעמדת ישראל בסדר זה על ההרים שהוא להשמיעם אמרות האמורות מפיהם ברוך אשר וגו' וארור אשר, ויונתן תרגם ויכרזון לואי, וקשה לי הרי הוא אומר קול רם, ואולי כי ההכרזה תהיה בקול לבד הרמת קול במאמר עצמו:
@34 **וענו כל העם ואמרו**. ולא הספיק לומר ואמר כל העם כדרך שאמר בכל הארורים האמורים בענין, העיר ה' בראשונה שצריך שישראל ישובו זה לא שהלוים יצטרכו לומר ואמר כל העם אלא דברי הכתוב הוא שמצוה שיענו העם ויאמרו אמן, ואין על הלוים לומר ואמר כל העם וגו':
@35 **ארור מקלה וגו'**. צריך לדעת למה לא בחר מכל העבירות לומר עליהם הארורים אלא אלו, גם בעריות למה לא יחד הארורים אלא לאלו והלא יש עריות חמורים כאלו והם הבא על אשת איש, ואולי כי לא אמר כאן אלא העבירות הטמונים והנסתרים, ולזה רשם בראשונה ואמר **ושם בסתר** כי העושה בדרך שיהיה מתגלה הנה נתחייבו ישראל בערבות זה על זה, וכן מה שאמר **ארור מקלה** פירוש שיעשה לו קלון בדרך שאינו נתפס עליו בבית דין של מטה, וכן השגת גבול הוא דבר שאינו ניכר, וכן משגה עור בדרך אין רואה, וכן הטית משפט השפלים, וכן הבא על אשת אביו ועל הבהמה ועל אחותו וחותנתו כלם אין הרגש לזולת המצאו עמהם לחקור בו, וכן מכה רעהו דקדק לומר בסתר, וכן לוקח שחד וגו' כגון שהיו בית דין שקול ובא אחד והכריע בסברתו בשביל שוחד גם זה הוא מדברים המסורים ללב ואין הרגש לזולת, וטעם שכתב **ארור שוכב עם בהמה** בין אשת אביו לאחותו, לומר כי כל כך מרוחק הדבר של אשת אב ואחות כשוכב עם בהמה שהוא דבר זר ומתועב לטבע אנושי:
@45 **ארור אשר לא יקים וגו' לעשות וגו'**. יש במשמעות הכתוב שכונתו לומר על דברים האמורים בענין, ויש במשמעותו שעל כל התורה הוא מדבר וכן פירשוהו ז''ל (סוטה ל''ז.), לדבריהם ז''ל טעם אומרו יקים לעשות, שאם היה אומר אשר לא יקים לבד או אשר לא יעשה לא היתה תקומה לשונאי ישראל כי מי הוא זה שיוכל לקיים את דברי התורה הזאת, ומה גם מי שאין סיפוק בידו לקיים כגון אין לו שדה לקיים מצות התלויות בה או אין לו עבד לקים מצות התלויות בו, לזה אמר **לעשות** פירוש שאינו בכלל ארור אלא מי שלא יקים עליו לעשות כשתשיג ידו עשות, ולזה לא אמר אשר לא יקים או אשר לא יעשה אלא אשר לא יקים לעשות פירוש יקים בלבו הדברים לעשותם כשתשיג ידו:
@46 **והיה אם שמוע וגו'**. צריך לדעת מקום גזירת הכתוב, אם הוא מאמר ונתנך וגו' היה לו לומר יתנך ה', כי מאומרו ונתנך משמע שמוסיף על הקודם, ואולי שגזירת הכתוב הוא תשמע בקול ה', והכונה בזה כי על ידי עסק התורה יעלה במעלות לזכות שה' ידבר בו, והוא אומרו **תשמע בקול ה' אלהיך**, עוד ימשך לך מהשמיעה לשמור ולעשות שהתורה מצלת מן החטא הרמוז בשמירה, גם תלמוד תורה גדול כחו שמביא לידי מעשה, והוא אומרו **ולעשות** ועוד לך ונתנך ה' עליון וגו', וחוץ מדרכינו יכוין הכתוב לומר שצריך שיעסוק בתורה בגדר מעלתם על הדברים שממקום קדוש עליון באו, והוא אומרו **תשמע** פירוש תהיה שמיעתך אותם כפי ערך המדבר אותם שהוא ה' אלהיך, ועוד **לשמור ולעשות** על דרך אומרם ז''ל (אבות פ''ד) הלומד על מנת ללמד מספיקין בידו ללמוד וללמד והלומד על מנת לעשות וכו' ע''כ, הרי שמובחר הלימוד הוא לקיים, והוא אומרו **אם שמוע תשמע** וגו' פירוש שתשמע לשמור ולעשות:
@46 **ונתנך ה' עליון וגו'**. הנה האדון חלק יעודי הטובה כנגד קיום המצות כל אחד כפי מה שראוי לו, כללות המצות הם ג' הרשומים בפסוק אם שמוע תשמע, והם תלמוד תורה, ושמירת לא תעשה, וקיום מצות עשה, כנגד תלמוד תורה יעד ברכה ונתנך ה' עליון ובאו עליך כל הברכות האלה והשיגוך, ופירוש הכתוב שזה יהיה כנגד שכר אם שמוע וגו' במה שגמר אומר כי תשמע בקול ה' אלהיך הרי שיעוד זה הוא כנגד שכר תלמוד תורה, והוא גם כן מכוון אליו כי באמצעות התורה ישתנו למעלה מכל האומות שאינם בני תורה, ואמר עוד **ובאו עליך כל הברכות** וגו' פירוש נוסף על יעוד ונתנך ה' עליון עוד לו ברכות אלו בשכר תורה, ואומרו **והשיגוך** יתבאר על דרך אומרם ז''ל (ילקוט ראובני פ' ויקרא) כי האדון אלהי ישראל מדותיו רחמים על הדופק על רחמיו ימלא ה' משאלותיו להריק עליו טובה כאשר יחפוץ אלא שבהגעת הטוב ההוא למטה ישפטו סנהדרי מעלה אם ראוי אם אינו ראוי לא יגיעו, לזה אמר והשיגוך הברכות שזה הוא עיקר ההבטחה שלא יתעכבו בבתי דינים שלמטה:
@46 **והנה** תמצא שכל הברכות האמורות בענין הם מכוונים כנגד שכר תלמוד תורה על זה הדרך, אומרו **ברוך אתה בעיר** וגו' על דרך אומרם ז''ל (ע''ז י''ט:) דבר זה כתוב בתורה ושנוי בנביאים ומשולש בכתובים כל העוסק בתלמוד תורה נכסיו מוצלחים, ואומרו **ברוך פרי בטנך** צא ולמד מעובד אדום הגיתי אשר נכנם אצלו ארון התורה מה עצמו פרי בטנו בזמן מועט כאומרם ז''ל (ברכות ס''ג:) שאשתו וח' כלותיו ילדו כאחד ששה בכרם אחד:
@46 **ואומרו ברוך אתה בבואך** וגו' שתהיה יציאתו מן העולם בלא חטא וכו', (ב''מ ק''ז.), וזה יהיה באמצעות תלמוד תורה שתגין עליו מהחטא:
@46 **ואומרו יתן ה' את אויביך** וגו' על דרך אומרו (דה''ב כ') ובעת החלו ברינה נתן ה' מארבים על בני עמון והר שעיר וגו' וינגפו, ואמרו רבותינו ז''ל (שמו''ר פמ''ז) אין רינה אלא תורה:
@46 **ואומרו יצו ה' אתך את הברכה** וגו', גם לא סדר ברכה זו למעלה עם הצלחות קנייני הטובות כי שם מקומה ולא אחר מפלת אויב, בא להבטיח שלא יארע לו אשר יארע לבעל הנס אשר יתקנאו בו המקטריגים על שנעשה לו דבר חדש ושמשוהו עליונים וזה הפך הטבע, וצא ולמד ממעשה רבא (תענית כ''ד:) שהוריד גשמים שלא בעתם וכדומה לזה, אשר על כן אמר סמוך למאמר **יתן ה' את אויביך** וגו' שזה הוא נס **יצו ה' אתך את הברכה** שלא ישלוט עין הרע בה, גם אמר **וברכך בארץ** וגו' פירוש שלא יאספו האומות עליכם לנקום נקמת הנגפים כמו שאמר יעקב לבניו במעשה שכם (וישלח ל''ד ל'):
@54 **יקימך ה' וגו'**. מכאן עד יפתח ה' לך את אוצרו הטוב הוא יעוד הטוב שכנגד שמירת מצות לא תעשה שרשם בתיבת לשמור, והוא מה שגמר אומר **כי תשמור את מצות ה'**, ואומרו **והלכת בדרכיו** לומר שלא צוה ה' אלא על הדברים שהוא מרחקם ויעוד זה מכוון הוא כנגד שמירת מצות לא תעשה כי באמצעות שיהיה האדם נשמר מהעבירות יקרא קדוש, דכתיב קדושים תהיו ופירוש הכתוב הדברים שבהם יהיו קדושים איש אמו וגו' ואת שבתותי וגו' אל תפנו אל וגו' ושאר אזהרות האמורים, וגם לדברי חז''ל (ויק''ר פכ''ד) שעל אזהרת העריות נאמר קדושים, הנה היא בכלל לשמור, ולזה אמר כנגד שמירת מצות לא תעשה יקימך ה' לו לעם קדוש, ודקדק לומר תיבת **לו** להעיר שיהיו ישראל במקום המלאכים שברר ה' לו לעמוד לפניו שנקראים קדושים דכתיב (דניאל ח') ויאמר אחד קדוש, יקים ה' אותנו במקומם לעם קדוש ויהיו המלאכים שיריים להם, וכן אמר (במדבר כ''ג) כעת יאמר ליעקב וגו' (במד''ר פ''כ):
@54 **ואומרו וראו כל עמי הארץ** וגו' גם זה הוא מכוון כנגד שמירת מצות לא תעשה, כי כל זמן שהאדם שומר עצמו מהעבירות אין צלם אלהים עובר מעל פניו וכל הנבראים אדם ובהמה מזדעזעים ממנו משא''כ המתעב מעשיו מעבירין ממנו הצלם וכמאמר קין (בראשית ד' י''ד) והיה כל מוצאי וגו':
@54 **והותירך ה' לטובה בפרי בטנך**. הגם שכבר אמר למעלה ברוך פרי בטנך, לפי שיעוד הראשון הוא כנגד תלמוד תורה ויעוד זה הוא כנגד שמירת המצות לזה הוצרך לפרט שכר כל א' שאין א' נלמד מחברו, ודקדק לומר **והותירך ה' לטובה** ולא אמר ברוך פרי בטנך, לפי שיעוד זה הוא מדה טובה שמכוונת כנגד שמירת מצות לא תעשה, והכוונה היא כי לפי שבאמצעות שמירת האדם עצמו מהעבירות לא ידבקו בו כוחי הרע שמזה יסובב שהבנים היוצאים ממנו יהיו מבחינת הרע, ועיין מה שכתבנו באורך בפרשת ויחי בפסוק ראובן בכורי אתה ויערבו לך הדברים, לזה אמר ביעוד שמירת מצות לא תעשה **והותירך ה' לטובה בפרי בטנך** שיהיו הבנים הנותרים אחריך למדה טובה ולא למדה רעה, ואומרו **בפרי בהמתך ובפרי אדמתך** לומר שמצד שמירת מל''ת יתקיימו בידו ב' דברים אלו כמו שיעדם לשכר תלמוד תורה ככתוב למעלה:
@57 **יפתח ה' וגו'**. מכאן מתחיל יעוד הטוב שכנגד מעשה המצות עד לבסוף, ולזה גמר אומר **כי תשמע אל מצות ה' אלהיך** אלו מצות עשה, והנה יעודים אלו הם מכוונים כנגד קיום המצות כי על ידי המצות מתפתחים צינורי השפע ומתייחדים המדות העליונות:
@57 **ואמר יפתח ה'** לך בכינוי שמבטיחו ה' שיפתח לו פירוש בשבילו לבד, הכוונה הגם שיסובבו אחרים לסתום באמצעות הצדיק יפתח אוצר הטוב ושם הטוב הוא סוד הנהר, והוא סוד (משלי י') צדיק יסוד עולם, ואומרו **את השמים** הוא סוד השפעה עליונה למעלה כידוע ליודעי חן, ואומרו **והלוית גוים רבים ואתה לא תלוה**, הנה ידוע שבזמן שישראל עושים רצונו של מקום השפע של כל העולם בא על ידי ישראל והעולם כלו ניזון מתמצית עם בני ישראל ולהיפך ניזונין ישראל מתחת ידי האומות, לזה אמר והלוית גוים רבים ואתה לא תלוה ממנו, הוצרך לומר ואתה לא תלוה, שאם לא כן אין היכר לברכה כי דרך העולם הוא שהגדולים והעשירים לווים זה מזה ולאחר מכן חוזר גם כן המלוה ולוה ממנו, לזה אמר **ואתה לא תלוה** ובזה יהיה היכר למאמר והלוית, ואומרו **ונתנך ה' לראש** וגו', פירוש שיהיו ישראל תחת ממשלת ראש העולם שהוא אלהי ישראל, ולא לזנב שהם שרי מעלה ובזה תמיד יהיו במדרגה העליונה כאומרו **והיית רק למעלה ולא תהיה למטה**, על דרך אומרם ז''ל (מדרש תנחומא ד''פ ויצא) בפסוק (ירמי' ל') ואתה אל תירא עבדי יעקב שראה יעקב בסולם עולים ואחר כך יורדים חשב שגם הוא כן אחר שיעלה ירד ת''ל אל תירא וגו', והוא אומרו ולא תהיה למטה, הטעם **כי תשמע** וגו' פירוש כנגד מצות עשה כמו שגמר אומר **ולעשות**, וטעם שלא אמר בפירוש כי תעשה מצות, לפי שיש מצות כמה וכמה שאינם ביד האדם לעשותם, לזה אמר כי תשמע וגו' **ולעשות** פירוש תקבל עליך לעשות, וטעם אומרו **לשמור** ביעוד זה, בא הכתוב להודיע כי אין יעוד למצות עשה אלא אחר שהקדים להם שמירת מצות לא תעשה, שאם לא כן זבחי רשעים תועבה, וכל מצוה שעושה בעל עבירות שורה עליה סטרא אחרא ואינה עושה פרי, לזה הקדים לומר לשמור ואחר כך אמר ולעשות שהוא מעשה המצות שעליו באו היעודים הטובים האמורים מוהותירך עד סוף:
@60 **והיה אם לא תשמע וגו'**. התנה הכתוב על ג' דברים תלמוד תורה, ושמירת מצות לא תעשה, וקיום מצות עשה, שצריך שיהיו שלשתם יחד, הכוונה שהגם שלמד תורה אם לא ישמור, או אם ישמור ולא יעשה, או אם יעשה שניהם ויבטל מתלמוד תורה, יבואו עליו הקללות רח''ל כאשר יבאר מה שנוגע לכל אחת מהנה עונש כל אחד בפני עצמו, והתחיל בעונש ביטול תלמוד תורה ואמר **ארור אתה בעיר** וגו' עד מאמר ועד אבדך מהר, וגמר אומר **מפני רוע מעלליך אשר עזבתני**, הרי שהקללות החמורות עד עתה הם כנגד עזיבת התורה כי העוזב תורה כעוזב ה', וכן תמצא שהקפיד ה' כל כך על עזיבת התורה ואמר (ירמי' ט') על מה אבדה הארץ ויאמר ה' על עזבם את תורתי, והוא אומרו כאן ועד אבדך מהר מפני רוע מעלליך **אשר עזבתני**:
@66 **ידבק ה' וגו'**. עונש זה וקללות האמורות עד ואתה תהיה לזנב, הם כנגד ביטול מצות לא תעשה, ולזה גמר אומר **ובאו עליך כל הקללות** וגו' **כי לא שמעת בקול ה' לשמור מצותיו**, הרי שקללות האמורות בענין הם על ביטול מצות לא תעשה, והמשכיל יבין בכל הקללות שהם רעות הנמשכות מהעבירות ואומרו **ידבק ה' בך** וגו', לפי שהעובר אפילו עבירה אחת קונה לו חלק רע שיהיה נדבק בנפשו לטמאה, והוא סוד תחלואי הנפש כידוע, וחלק הרע נקרא דבר על דרך אז''ל (תוס' מם' שבת פ''ט. ד''ה תורה) בפסוק (חבקוק ג') לפניו ילך דבר, שידבר על ס''מ הרשע שנקרא דבר, וידוע שכל כוחי הרע הם ענפיו של ס''מ ויקראו על שמו, גם קללת שחפת וקדחת וכו' הם דברים המסובבים מהעבירות על דרך אומרם בגמ' (שבת נ''ה.) אמר ר' אמי אין מיתה בלא חטא ואין יסורין בלא עון, כי העון יוליד תחלואים בגוף כאומרו (ירמי' כ') תיסרך רעתך וגו', וכן אומרו **והיו שמיך** וגו' על דרך אומרם ז''ל (זוהר ח''א ו') שבאמצעות העבירות יסתתמו פתחי ההשפעות בסוד (איוב י''ד) ונהר יחרב ויבש, וכן אומרו **יתנך ה' נגף** וגו' גם זה יסובבו העבירו' כרמוז בפסוק (קהלת ח') אשר ישלוט האדם באדם לרע לו, פירוש לסיבת הרע אשר לו דבוקה בו כרמוז במאמר ידבק ה' בך את הדבר, וכן כל הקללות האמורים בענין יסובבו ממעשה הרעה:
@66 **ואומרו והיו בך לאות ולמופת**. (להלן פסוק מו) כי העובר עבירה אחת נרשמת על מצחו:
@66 **ואומרו ובזרעך עד עולם**. כי נפש אדם רע על ידי שדבוקים בה חלקי הטומאה כמו שאמרנו בניהם אשר יולידו כמוהם יהיו, כמו שביארנו באר היטב דבר זה בפרשת ויחי בפסוק ראובן בכורי אתה, גם זה הוא סוד מיתה שנגזרה על אדם ועל כל דורות הבאים ממנו מטעם שכל היוצאים ממנו טעמו מות בחטאו, והוא סוד ערלת אדם, לזה אמר **ובז רעך עד עולם** כי כשידבק חלק הרע עם האדם ישתלשל מזה לזה עד עולם וצריך עוצם רב לנקותו מנפשו:
@92 **תחת אשר לא עבדת וגו'**. עונש זה והבא אחריו עד אומרו אם לא תשמוד הוא כנגד ביטול מצות עשה שרשם בפסוק (כח) אם לא תשמור לעשות וגו'; ואמר **תחת אשר לא עבדת את ה'** פירוש לעשות מצות אשר צוך לעשות בשמחה לזה ועבדת את אויביך ברעב ובצמא וגו', אתה פרקת עול המצוה מעליך יתן אויביך עול ברזל על צוארך, ועונשים אלי הם מכוונים כנגד פריקת עול מצות עשה, אתה שלא רצית לטרוח להבין ולהשכיל סדר מעשה המצות ישא ה' עליך גוי אשר לא תשמע לשונו וגו' וכן כולן:
@92 **וגמר** אומר **אם לא תשמור לעשות**, להודיע כי על קיום מצות עשה הוא מעניש, וכלל כל מצות עשה במצות היראה כי היא מצות עשה כמו שכתב רמב''ם בתחלת ספר המדע (הל' יסודי התורה פ''ב) וז''ל השם הנכבד וכו' מצוה ליראה וכו', וטעם שלא אמר אם לא תעשו, כתבתי למעלה (כ''ז כ''ו) טעם שלא יחייב לעשות בדרך כלל אלא לשמור לעשות כשיבא לידו וכשישיג לעשות:
@92 **או** אפשר שפסוק זה בא לומר על דרך אומרו (ויקרא כ''ו כ''ג) ואם באלה לא תוסרו לי פירוש שאם אחר כל האמור לא ישמור לעשות וגו' ליראה ה' הנכבד והנורא, שאחר שהביא עליו כל הקללות יהיה בעיניו נורא מאוד כי ראה אשר יסרו, ודקדק לומר **תשמור לעשות** כנגד מצות לא תעשה ומצות עשה, והודיע שיפליא ה' עוד בו מכות גדולות וכל האמור בענין, וגמר אומר **ונשארתם במתי מעט** וגו' תחת אשר וגו' **כי לא שמעת בקול ה' אלהיך** זה כנגד מה שלא עשה תשובה על ביטול תלמוד תורה, **והיה כאשר שש** וגו' לבל יאמר אדם אחר שידענו כי ה' אלהינו מדותיו כלן מדות החסד והרחמים מדותיו ימנעוהו מהאריך עוד בצרות וירף ידו, לזה הודיע כי שמחה היא לו כאשר שש וגו' וכפי זה אין הטבע קץ מהשמחות, וכיוצא בזה אמר הכתוב (משלי י''א) באבוד רשעים רנה, וכן דרשו רבותינו ז''ל (סנהדרין ל''ט:) בפסוק (מ''א כ''ג) ותעבור הרינה שהיה באבוד אחאב בן עמרי רינה לפני ה', ויונתן תרגם ישיש ה' יחדי מימרא דה' עליכון עממין נוכראין וכו' ודקדק ישיש פועל יוצא לאחרים, אף על פי כן פשט הכתוב אינה נעקרת ממקומה וכמו שתרגם אונקלוס, אלא שיונתן בן עוזיאל דרש הכתוב:
@92 **וראיתי** להעיר למה לא נאמרו נחמות בקללות האלו כסדר האמור בקללות שבפרשת בחקותי, גם יש להעיר למה כפל הקללות ולא הספיק קללות שאמר בפרשת בחקתי:
@92 **ונראה** כי הוצרך לכפול הקללות לפי שקללות שבפרשת בחקתי נאמרו לכללות ישראל שכן נאמרו כולם בלשון רבים מתחלתם ועד סופם, ויש מקום לומר שאם חלק מישראל יטיבו מעשיהם אין ה' מקפיד על חלק המרשיע, לזה באו קללות האמורים בפרשה זו ונאמרו כולן בל' יחיד, ונתכוון לדבר בין בערך יחיד ממש בין בערך חלק מישראל הגם שיהיו רבים בערך כללות ישראל יתיחס להם יחיד, ולזה תמצא שאמר והיו **שמיך אשר על ראשך** וגו' **ישא ה' עליך** גוי מרחוק, זה כנגד חלק מישראל הגם שהם רבים יאמר להם לשון יחיד מטעם שכתבנו, ואמר גם כן אשה תארש וגו' בית תבנה וגו' סתמו ביחיד ממש:
@92 **ומעתה** הרוחנו למה לא נאמרה נחמה בהם, כי לא נאמרה נחמה אלא בקללה שהם לכללות ישראל כי לא יעזבם לכלותם ושיזכור להם ברית אבותם גם יזכור הארץ, משא''כ היחידים מהם כי ירשיעו אש תאכלם עד עולם, והלא תמצא שצוה ה' לאבד עיר מישראל ולשומה תל עולם והיא עיר הנדחת, ואין צריך לומר אדם כי ירשיע להמיתו בבית דין, ומה נחמה יש לזה אחר אובדו, וכן תמצא בפרשת נצבים כשהזכיר ה' רשעת משפחה אחת ושבט אמר (כ''ט י''ט) ומחה ה' את שמו וגו' ולא הזכיר נחמתו, וכמו כן בקללות האמורים בפרשה זו להיותם ליחידים מישראל. ואל יקשה בעיניך מה שדיבר הכתוב ב' או ג' תיבות בפרשה זו בלשון רבים כאומרו **ונשארתם מתי מספר**, **להאביד אתכם**, **והתמכרתם**, כי אחר שקדם לדבר בלשון יחיד לא הקפיד לגמור אומר בלשון רבים, כי הדברים מובנים שעל רבים שביחידים הוא אומר, והעד לאויביך לשון יחיד:
@92 **ואם** תאמר היה לו לומר קללות שבבחקותי בלשון יחיד ולא היה צריך לכפול קללות אלו, שהייתי אומר שלא יעניש הכתוב כל העונש החמור אלא ליחידים אבל לכללות ישראל לא, או הגם שנאמר שחטאם גדול ונלמד מעונש היחידים אין לנו הבטחת הנחמה שיזכור ה' את ברית האבות, תלמוד לומר קללות שבבחקותי לומר שגם הכללות יענשו כזה, וכי יש להם נחמה לבל יפר ה' ברית אבותינו ושב את שבותינו:
@92 **נמצינו** אומרים שיענש ה' על ביטול תלמוד תורה, ועל העובר על מצות לא תעשה ועל המבטל מצות עשה, והגם שאמרו בגמרא (מנחות מ''א.) שאין מענישים על עשה אלא בעידן ריתחא, יש מצות עשה שחייבין עליהם כגון מילה ופסח, גם המסכים בדעתו לכפור במצות עשה לבל עשות אותם את זה יקלל ה' ויכינהו לפורענות ככל הכתוב:
@92 (נט) **מכות גדולות ונאמנות וחלים רעים ונאמנים**. אומרו **נאמנים** נתכוון לומר שהגם שיעשו להם רפואה טבעית שיוסרו בה אף על פי כן נאמנים בשליחותם מהם לא יזועו עד בא דבר ה' לסור ממנו:
@115 **ויקרא משה אל כל ישראל וגו'**. הגם שעד עתה היה מדבר אל כל ישראל, הוסיף לקבץ הנשים והטף והגרים כאמור בסמוך אתם נצבים היום כלכם וגו' טפכם וגו':
@115 **חסלת פרשת תבא**
